-- MAIL-DRAFT-1 (qnfo-fleet-dashboard 1.34.0, 2026-10-13, pillar personal): failure mode and detector for reply drafts that
-- invent facts about the owner. Owner, 2026-10-13: "NEVER INVENT TITLES ('MACHINE LEARNING ENGINEER') OR BUSINESS UNITS
-- ('QNFO OPERATIONS') OR FABRICATE ANY OTHER INFORMATION. THIS WAS A SIMPLE REQUEST BUT IS REQUIRING MULTIPLE BACK-AND-FORTH
-- PROMPTS". The detector counts mail sent from a fleet address since the fix that carries an unfilled [[FILL gap or either
-- invented signature line; expected 0.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class = 'fm-mail-draft-fabrication'; DELETE FROM failure_modes WHERE fm_key = 'mail-draft-fabrication';
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('mail-draft-fabrication', 'a reply drafted on fleet.qnfo.org invents facts about the owner (a job title, a business unit, how he found a paper, production use, a letterhead) and needs several prompts before it can be sent', 'a draft request went to the general command-line question prompt, which held three stored lines of the message, no rule about statements made in the owner''s name and a JSON answer format, so the model filled the signature and the facts from nowhere, its escaped newlines showed as backslash-n, and sending needed the text retyped into reply <id>', 'qnfo-fleet-dashboard 1.34.0 MAIL-DRAFT-1: a dedicated drafting path (message found by address, id or card; the stored thread; only the owner''s name as an owner fact; [[FILL: ...]] gaps for anything not on record; titles and units the thread lacks replaced in code; sign-off written in code; Edit, then send and Send reply buttons; send it; conMailReply refuses a reply that still holds a gap)', 'no mail sent from a fleet address after the 1.34.0 deploy holds a [[FILL gap or an invented signature line', 'fm-mail-draft-fabrication', '2026-10-13', NULL, 'a model writes text the owner sends in his own name with no grounding rule and no code-side check', 'a draft signed with a title or unit the owner never gave, or claims about the owner nobody recorded', 'every correspondent the owner answers from the fleet dashboard, including statements used in legal filings');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, budget_ms, max_items, requires_container) VALUES
 ('fm-mail-draft-fabrication', NULL, 'MAIL-DRAFT-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM emails WHERE lower(sender) LIKE ''%@qnfo.org%'' AND received_at >= ''2026-10-13T08:00:00Z'' AND (body_text LIKE ''%[[FILL%'' OR body_text LIKE ''%Machine Learning Engineer, QNFO%'' OR body_text LIKE ''%QNFO Operations%'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-dashboard', 1, 'holding', 'failure-mode', 45000, 5, 0);
